import { cn } from "@/lib/utils"

/**
 * One source the AI read, opened from its evidence chip.
 * The bar shows today's reading against the normal range; the tick is the 30-day baseline.
 */
export interface EvidenceCardProps {
  n: number
  source: string
  value: string
  unit?: string
  /** Today's reading, 0–1 of the bar. */
  now: number
  /** The normal range, 0–1 of the bar. */
  normal?: [number, number]
  /** The 30-day baseline, 0–1 of the bar. */
  baseline?: number
  caption: string
  /** Its chip or drawing mark is hovered elsewhere. */
  linked?: boolean
  /** Reading is older than 15 minutes. */
  stale?: boolean
  age?: string
  className?: string
}

export function EvidenceCard({ n, source, value, unit, now, normal = [0, 0.62], baseline = 0.62, caption, linked = false, stale = false, age = "15 min", className }: EvidenceCardProps) {
  return (
    <div
      data-slot="evidence-card"
      className={cn(
        "grid gap-2 bg-[var(--gc-glass-raised)] p-4 shadow-[inset_0_1px_0_var(--gc-edge-hi)] transition-shadow duration-200 ease-gc",
        linked && "shadow-[inset_0_0_0_1.5px_var(--gc-accent)]",
        stale && "opacity-60",
        className
      )}
    >
      <div className="flex items-baseline justify-between gap-3">
        <span className="font-mono text-[11px] uppercase tracking-[0.05em] text-muted-foreground">{n} · {source}</span>
        {stale && <span className="font-mono text-xs text-muted-foreground">{age} ago</span>}
      </div>
      <div className="flex items-baseline gap-2">
        <span className="text-xl font-medium">{value}</span>
        {unit && <span className="text-[13px] text-muted-foreground">{unit}</span>}
      </div>
      <div className="relative h-1.5 bg-border">
        <i className="absolute inset-y-0 bg-muted-foreground/30" style={{ left: `${normal[0] * 100}%`, width: `${(normal[1] - normal[0]) * 100}%` }} />
        <i className="absolute inset-y-0 left-0 bg-signal" style={{ width: `${now * 100}%` }} />
        <i className="absolute -inset-y-1 w-px bg-foreground" style={{ left: `${baseline * 100}%` }} />
      </div>
      <span className="text-[13px] text-muted-foreground">{caption}</span>
    </div>
  )
}
